package com.supportsphere.controller; import com.supportsphere.dao.*; import com.supportsphere.model.*; import com.supportsphere.service.RequestService; import com.supportsphere.util.*; import javafx.fxml.*; import javafx.collections.*; import javafx.scene.control.*; import java.util.*;
public class AdminDashboardController { @FXML Label users,volunteers,open,active,completed,avg; @FXML TableView<Map<String,Object>> requestsTable,usersTable; @FXML TableColumn<Map<String,Object>,String> reqCol,userCol; private final AdminDAO dao=new AdminDAO(); private final UserDAO usersDao=new UserDAO(); private final VolunteerDAO volDao=new VolunteerDAO(); private final RequestService req=new com.supportsphere.service.RequestService(); @FXML void initialize(){load();} private void load(){try{Map<String,Integer>s=dao.stats();users.setText(""+s.get("Total Users"));volunteers.setText(""+s.get("Active Volunteers"));open.setText(""+s.get("Open Requests"));active.setText(""+s.get("Active Assignments"));completed.setText(""+s.get("Completed Tasks"));List<User>us=usersDao.findAll();ObservableList<Map<String,Object>> rows=FXCollections.observableArrayList();for(User u:us){Map<String,Object>m=new LinkedHashMap<>();m.put("user",u.getName()+" · "+u.getRole());m.put("id",u.getUserId());m.put("status",u.getRole());rows.add(m);}usersTable.setItems(rows);userCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(String.valueOf(c.getValue().get("user"))));List<AssistanceRequest>rs=req.all();ObservableList<Map<String,Object>> rr=FXCollections.observableArrayList();for(AssistanceRequest r:rs){Map<String,Object>m=new LinkedHashMap<>();m.put("req","#"+r.getRequestId()+" · "+r.getTaskType()+" · "+r.getStatus()+" · "+(r.getVolunteerName()==null?"—":r.getVolunteerName()));rr.add(m);}requestsTable.setItems(rr);reqCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(String.valueOf(c.getValue().get("req"))));}catch(Exception e){Dialogs.error("Admin dashboard error",e.getMessage());}} @FXML void verify(){Map<String,Object>m=usersTable.getSelectionModel().getSelectedItem();if(m==null){Dialogs.info("Select a volunteer","Select a user row first.");return;}try{int id=(int)m.get("id");User u=usersDao.findById(id).orElseThrow();if(u.getRole()!=Role.VOLUNTEER){Dialogs.info("Not a volunteer","Verification applies to volunteer accounts.");return;}volDao.updateVerification(id,"VERIFIED");Dialogs.info("Volunteer verified","The volunteer is now verified and can receive recommendations.");load();}catch(Exception e){Dialogs.error("Could not verify",e.getMessage());}} @FXML void block(){Map<String,Object>m=usersTable.getSelectionModel().getSelectedItem();if(m==null)return;try{int id=(int)m.get("id");if(id==Session.getUser().getUserId()){Dialogs.info("Not allowed","You cannot block the current admin account.");return;}usersDao.setStatus(id,"BLOCKED");load();}catch(Exception e){Dialogs.error("Could not update user",e.getMessage());}} @FXML void assignments(){try{StringBuilder b=new StringBuilder();for(var x:dao.assignments())b.append(x.get("assignment_id")).append(" · Request #").append(x.get("request_id")).append(" · ").append(x.get("volunteer")).append(" · ").append(x.get("assignment_status")).append("\n");Dialogs.info("Assignments",b.length()==0?"No assignments yet.":b.toString());}catch(Exception e){Dialogs.error("Could not load assignments",e.getMessage());}} @FXML void feedback(){try{StringBuilder b=new StringBuilder();for(var x:dao.feedback())b.append("#").append(x.get("request_id")).append(" · ").append(x.get("volunteer")).append(" · ").append(x.get("rating")).append("★\n").append(x.get("comment")).append("\n\n");Dialogs.info("Feedback",b.length()==0?"No feedback yet.":b.toString());}catch(Exception e){Dialogs.error("Could not load feedback",e.getMessage());}} @FXML void logout(){Session.clear();try{SceneManager.show("login.fxml","SupportSphere — Sign in");}catch(Exception e){}} }
